import{_ as a,C as n,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.6","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Draft I0.6","outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i0.6/part-01.md","filePath":"en/publications/implementation-case-i0.6/part-01.md","lastUpdated":1786085052000}'),d={name:"en/publications/implementation-case-i0.6/part-01.md"};function c(p,e,l,u,h,m){const t=n("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An S0.5 author-run engineering evidence baseline across the Reference Reader, FCoP, CodeFlowMu, and WP-13.",version:"I0.6",status:"S0.5 engineering evidence draft",languageHref:"/zh/publications/implementation-case-i0.6",languageLabel:"简体中文"}),e[0]||(e[0]=s(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="s0-5-reference-reader-fcop-v3-2-5-codeflowmu-local-snapshot-and-wp-13" tabindex="-1">S0.5 Reference Reader, FCoP v3.2.5, CodeFlowMu Local Snapshot, and WP-13 <a class="header-anchor" href="#s0-5-reference-reader-fcop-v3-2-5-codeflowmu-local-snapshot-and-wp-13" aria-label="Permalink to &quot;S0.5 Reference Reader, FCoP v3.2.5, CodeFlowMu Local Snapshot, and WP-13&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> Draft I0.6<br><strong>Status:</strong> Author-produced implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a><br><strong>Historical Baseline:</strong> I0.5 preserves the S0.4 corpus and WP-13 publication package<br><strong>Evidence Capture:</strong> 2026-08-07, Asia/Shanghai<br><strong>Evidence Package:</strong> <code>tmpa-i0.6-local-evidence-20260806-v2</code><br><strong>Authority Boundary:</strong> This report is evidentiary and non-normative. Only the Core Specification defines TMPA requirements.</p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I0.6 is the first Implementation Case revision to evaluate fresh product evidence against TMPA Core S0.5. It combines four deliberately separate tracks: the S0.5 Reference Reader, the FCoP v3.2.5 protocol reference implementation, an isolated byte-for-byte snapshot of a local CodeFlowMu worktree, and the previously published WP-13 multi-agent evidence-gating case. XiaoDian AI remains lineage and candidate field evidence; no fixed XiaoDian S0.5 package was run.</p><p>The S0.5 Reference Reader passes <strong>14/14</strong> author-produced synthetic criteria. Product evidence does not inherit those results. The product-level matrix is <strong>1 PASS, 8 PARTIAL, 3 NOT RUN, and 2 FAIL</strong>: C14 passes; C02 and C07 fail; C01, C03–C06, C09, C10, and C13 are partial; C08, C11, and C12 were not run. FCoP records 1,222 passed, 3 failed, and 2 skipped tests. CodeFlowMu records 8/8 protocol fixtures, 1,420 passed / 1 failed / 1 skipped Runtime tests, 770/770 Shell tests, and successful type checks for Protocol, Runtime, and Shell.</p><p>The evidence therefore supports implementation and author-demonstrated behavior, not complete S0.5 conformance, independent validation, or independent adoption. Failures are retained as evidence. WP-13 demonstrates governance containment of an unverified completion claim; it does not prove that a model ceased to hallucinate.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>This report asks:</p><ol><li>Can the S0.5 normative interpretation be executed deterministically by the published Reference Reader?</li><li>Which S0.5 criteria have current product-level evidence in FCoP and CodeFlowMu?</li><li>Where do observed product behaviors still diverge from the Core contract?</li><li>What does WP-13 demonstrate about multi-agent evidence gating under uncertain tool results?</li></ol><p>The unit of judgment is a criterion-bound evidence claim, not a product reputation claim. The report uses four maturity labels without collapsing them:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning in I0.6</th></tr></thead><tbody><tr><td>Specified</td><td>Defined by TMPA Core S0.5</td></tr><tr><td>Implemented</td><td>A corresponding mechanism exists in code or protocol artifacts</td></tr><tr><td>Demonstrated</td><td>An author-run execution produced inspectable evidence</td></tr><tr><td>Independently Adopted</td><td>A separate organization adopted and validated the mechanism</td></tr></tbody></table><p>No I0.6 claim reaches independently adopted.</p><h1 id="_2-architecture-and-component-boundaries" tabindex="-1">2. Architecture and Component Boundaries <a class="header-anchor" href="#_2-architecture-and-component-boundaries" aria-label="Permalink to &quot;2. Architecture and Component Boundaries&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture</span></span>
<span class="line"><span>       ↓ normative contract</span></span>
<span class="line"><span>TMPA Core S0.5</span></span>
<span class="line"><span>       ↓ reusable protocol profile</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>       ↓ reference implementation</span></span>
<span class="line"><span>fcop / fcop-mcp</span></span>
<span class="line"><span>       ↓ downstream adoption</span></span>
<span class="line"><span>CodeFlowMu application and WP-13 workflow</span></span></code></pre></div><p>TMPA is the governance architecture. FCoP is a reusable protocol profile, not an application and not a <code>pip install</code> product claim. The <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of that protocol. CodeFlowMu is a downstream application that uses FCoP concepts and operations for persistent roles, tasks, reports, reviews, recovery, and audit surfaces. WP-13 is one bounded CodeFlowMu field case. XiaoDian AI belongs to the engineering lineage but was not executed as an S0.5 product input in this run.</p><p>Conceptual layering and historical lineage remain distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONCEPTUAL: TMPA → FCoP → CodeFlowMu / other applications</span></span>
<span class="line"><span>HISTORICAL: XiaoDian practice → early TMPA → FCoP extraction</span></span>
<span class="line"><span>                                   → CodeFlowMu → current TMPA formalization</span></span></code></pre></div><h1 id="_3-evidence-design-and-fixed-sources" tabindex="-1">3. Evidence Design and Fixed Sources <a class="header-anchor" href="#_3-evidence-design-and-fixed-sources" aria-label="Permalink to &quot;3. Evidence Design and Fixed Sources&quot;">​</a></h1><p>The V2 package preserves commands, environments, stdout/stderr logs, structured summaries, a criterion matrix, source inventory, privacy-redaction report, and SHA-256 manifest. V2 corrects a narrative error in V1 without rerunning or altering any raw product log.</p><table tabindex="0"><thead><tr><th>Source</th><th>Fixed identity</th><th>Evidence role</th><th>Boundary</th></tr></thead><tbody><tr><td>TMPA publication</td><td>Commit <code>653e7ba0…</code></td><td>S0.5 schemas, fixtures, and Reference Reader</td><td>Author implementation</td></tr><tr><td>FCoP</td><td>Tag <code>v3.2.5</code>, commit <code>b3dc2343…</code></td><td>Protocol and clean detached reference implementation</td><td>Public fixed source</td></tr><tr><td>CodeFlowMu</td><td>Base <code>c4ebc146…</code>, version <code>0.3.0-alpha</code></td><td>Isolated product/test snapshot</td><td>Dirty local source: 39 modified and 47 untracked files</td></tr><tr><td>WP-13</td><td>Commit <code>609571dd…</code>, V3 ZIP SHA-256 <code>5b5eda30…</code></td><td>Multi-agent fact-check field case</td><td>Author-produced, role-separated QA; not third-party validation</td></tr><tr><td>XiaoDian AI</td><td>No fixed S0.5 package</td><td>Lineage and candidate case</td><td>NOT RUN</td></tr></tbody></table><p>The CodeFlowMu snapshot is byte-for-byte isolated from the working tree for execution, but it is not a stable public release. It can support author-run local evidence only.</p><h1 id="_4-fcop-and-codeflowmu-engineering-mapping" tabindex="-1">4. FCoP and CodeFlowMu Engineering Mapping <a class="header-anchor" href="#_4-fcop-and-codeflowmu-engineering-mapping" aria-label="Permalink to &quot;4. FCoP and CodeFlowMu Engineering Mapping&quot;">​</a></h1><p>FCoP provides project-visible coordination through routed textual objects, lifecycle paths, atomic publication, append-only transitions, explicit roles, independent reports and reviews, issues, alerts, and history. Its project-visible model supports reconstruction outside a transient agent session.</p><p>CodeFlowMu adds application runtime behavior: persistent work identities, PM/DEV/QA/OPS role interfaces, skill and tool invocation, workflow scheduling, review gates, dependency waiting, recovery, approval boundaries, and user-facing operational views. These application mechanisms may implement or demonstrate parts of S0.5, but they do not redefine the FCoP protocol or TMPA Core criteria.</p><p>The principal common gap is a maintained product projection that converts native artifacts into the complete S0.5 governance-object and Reader-result surface. Without that projection, local controls may work while canonical objects, issue codes, three-valued judgments, and deterministic aggregate views remain incomplete.</p>`,26))])}const b=a(d,[["render",c]]);export{f as __pageData,b as default};
